package middleware

func Retry(n int, backoff time.Duration) Middleware {
	return func(next Handler) Handler {
		return func(ctx context.Context, req *Request) (*Response, error) {
			var last error
			for i := 0; i < n; i++ {
				resp, err := next(ctx, req)
				if err == nil {
					return resp, nil
				}
				last = err
				time.Sleep(backoff)
			}
			return nil, last
		}
	}
}
